s=s.replace('<label>Opis / zakres prac</label><textarea id="bScope" rows="3" placeholder="np. elektryka, hydraulika, rekuperacja, pompa ciepła..."></textarea>\n      <label>Uwagi</label><textarea id="bNotes" rows="3"></textarea><div class="toolbar"><button onclick="saveBuildingRecord()">Zapisz budowę</button></div>', '''<label>Opis / zakres prac</label><textarea id="bScope" rows="3" placeholder="np. elektryka, hydraulika, rekuperacja, pompa ciepła..."></textarea>
      <div class="card" style="margin-top:12px"><h3>Branże na budowie</h3><div class="grid3" id="bIndustries">
        <label><input type="checkbox" value="Hydraulika" style="width:auto"> Hydraulika</label><label><input type="checkbox" value="Elektryka" style="width:auto"> Elektryka</label><label><input type="checkbox" value="Wentylacja" style="width:auto"> Wentylacja</label><label><input type="checkbox" value="Klimatyzacja" style="width:auto"> Klimatyzacja</label><label><input type="checkbox" value="Pompa ciepła" style="width:auto"> Pompa ciepła</label><label><input type="checkbox" value="Gaz" style="width:auto"> Gaz</label><label><input type="checkbox" value="Automatyka" style="width:auto"> Automatyka</label><label><input type="checkbox" value="Fotowoltaika" style="width:auto"> Fotowoltaika</label><label><input type="checkbox" value="Inne" style="width:auto"> Inne</label>
      </div></div>
      <div class="grid"><div><label>Ekipa / pracownicy</label><textarea id="bTeam" rows="3" placeholder="jedna osoba w linii"></textarea></div><div><label>Budżet orientacyjny [zł]</label><input id="bBudget" type="number" step="0.01" min="0"></div></div>
      <div class="grid"><div><label>Etapy prac — jeden w linii</label><textarea id="bStages" rows="6" placeholder="Trasowanie\nInstalacja podposadzkowa\nRozdzielnia\nUruchomienie"></textarea></div><div><label>Materiały / zapotrzebowanie — jeden w linii</label><textarea id="bMaterials" rows="6" placeholder="Rura PEX 16 — 200 m\nPrzewód YDY 3x2,5 — 300 m"></textarea></div></div>
      <label>Uwagi</label><textarea id="bNotes" rows="3"></textarea><div class="toolbar"><button onclick="saveBuildingRecord()">Zapisz budowę</button></div>''')
s=s.replace('<div class="grid"><div class="card"><div class="label">Folderów</div><div class="stat" id="buildingFolderCount">0</div></div><div class="card"><div class="label">Podfolderów</div><div class="stat" id="buildingSubfolderCount">0</div></div><div class="card"><div class="label">Plików</div><div class="stat" id="buildingFileCount">0</div></div></div>', '<div class="grid"><div class="card"><div class="label">Postęp</div><div class="stat" id="buildingProgress">0%</div></div><div class="card"><div class="label">Folderów</div><div class="stat" id="buildingFolderCount">0</div></div><div class="card"><div class="label">Plików</div><div class="stat" id="buildingFileCount">0</div></div><div class="card"><div class="label">Budżet</div><div class="stat money" id="buildingBudget">0,00 zł</div></div></div><div class="grid"><div class="card"><h3>🔧 Branże</h3><div id="buildingIndustries" class="meta"></div></div><div class="card"><h3>👷 Ekipa</h3><div id="buildingTeam" class="meta"></div></div></div><div class="grid"><div class="card"><div class="pageHeader"><h3>✅ Etapy prac</h3><button class="secondary smallBtn" onclick="toggleBuildingStageEditor()">Edytuj postęp</button></div><div id="buildingStages"></div></div><div class="card"><h3>📦 Materiały / zapotrzebowanie</h3><div id="buildingMaterials"></div></div></div>')
html.write_text(s,encoding='utf-8')

js=Path('js/modules/buildings.js')
s=js.read_text(encoding='utf-8')
s=s.replace("function statusClass(s){return s==='Zakończona'?'ok':s==='Wstrzymana'?'warn':s==='W trakcie'?'info':''}", "function statusClass(s){return s==='Zakończona'?'ok':s==='Wstrzymana'?'warn':s==='W trakcie'?'info':s==='Oferta'?'purple':''}\nfunction money(n){return Number(n||0).toFixed(2).replace('.',',')+' zł'}\nfunction stageProgress(x){const a=x?.stages||[];if(!a.length)return 0;return Math.round(a.filter(v=>v.done).length/a.length*100)}")
old="window.openBuildingForm=id=>{if(!(id?perm('edit'):perm('add')))return alert('Brak uprawnienia.');const x=buildings.find(v=>v.id===id)||{};$('bId').value=x.id||'';$('bName').value=x.name||'';$('bClient').value=x.client||'';$('bAddress').value=x.address||'';$('bStatus').value=x.status||'Planowana';$('bStart').value=x.startDate||'';$('bEnd').value=x.endDate||'';$('bScope').value=x.scope||'';$('bNotes').value=x.notes||'';$('buildingFormTitle').textContent=id?'Edytuj budowę':'Nowa budowa';$('buildingEditor').classList.remove('hidden');$('buildingEditor').scrollIntoView({behavior:'smooth',block:'start'});};"
new="window.openBuildingForm=id=>{if(!(id?perm('edit'):perm('add')))return alert('Brak uprawnienia.');const x=buildings.find(v=>v.id===id)||{};$('bId').value=x.id||'';$('bName').value=x.name||'';$('bClient').value=x.client||'';$('bAddress').value=x.address||'';$('bStatus').value=x.status||'Planowana';$('bStart').value=x.startDate||'';$('bEnd').value=x.endDate||'';$('bScope').value=x.scope||'';$('bTeam').value=(x.team||[]).join('\\n');$('bBudget').value=x.budget||'';$('bStages').value=(x.stages||[]).map(v=>v.name).join('\\n');$('bMaterials').value=(x.materials||[]).join('\\n');document.querySelectorAll('#bIndustries input[type=checkbox]').forEach(el=>el.checked=(x.industries||[]).includes(el.value));$('bNotes').value=x.notes||'';$('buildingFormTitle').textContent=id?'Edytuj budowę':'Nowa budowa';$('buildingEditor').classList.remove('hidden');$('buildingEditor').scrollIntoView({behavior:'smooth',block:'start'});};"
if old not in s: raise SystemExit('openBuildingForm pattern not found')
s=s.replace(old,new,1)
old="const data={companyId,ownerUid:profile?.ownerUid||auth.currentUser.uid,name:$('bName').value.trim(),client:$('bClient').value.trim(),address:$('bAddress').value.trim(),status:$('bStatus').value,startDate:$('bStart').value,endDate:$('bEnd').value,scope:$('bScope').value.trim(),notes:$('bNotes').value.trim(),updatedAt:now()};"
new="const oldRec=buildings.find(v=>v.id===id)||{},oldStages=oldRec.stages||[],stageNames=$('bStages').value.split(/\\n/).map(v=>v.trim()).filter(Boolean),stages=stageNames.map(name=>({name,done:oldStages.find(v=>v.name===name)?.done||false}));const data={companyId,ownerUid:profile?.ownerUid||auth.currentUser.uid,name:$('bName').value.trim(),client:$('bClient').value.trim(),address:$('bAddress').value.trim(),status:$('bStatus').value,startDate:$('bStart').value,endDate:$('bEnd').value,scope:$('bScope').value.trim(),industries:[...document.querySelectorAll('#bIndustries input[type=checkbox]:checked')].map(el=>el.value),team:$('bTeam').value.split(/\\n/).map(v=>v.trim()).filter(Boolean),budget:Number($('bBudget').value||0),stages,materials:$('bMaterials').value.split(/\\n/).map(v=>v.trim()).filter(Boolean),notes:$('bNotes').value.trim(),updatedAt:now()};"
if old not in s: raise SystemExit('save data pattern not found')
s=s.replace(old,new,1)
s=s.replace("<div class=\"stat\">${(x.folders||[]).length} 📁</div>", "<div><div class=\"stat\">${stageProgress(x)}%</div><div class=\"meta\">${(x.folders||[]).length} 📁</div></div>")
old="const folders=x.folders||[],subs=folders.filter(f=>f.parentId).length,fileCount=folders.reduce((n,f)=>n+(f.files||[]).length,0);$('buildingFolderCount').textContent=folders.length;$('buildingSubfolderCount').textContent=subs;if($('buildingFileCount'))$('buildingFileCount').textContent=fileCount;"
new="const folders=x.folders||[],fileCount=folders.reduce((n,f)=>n+(f.files||[]).length,0);if($('buildingProgress'))$('buildingProgress').textContent=stageProgress(x)+'%';$('buildingFolderCount').textContent=folders.length;if($('buildingFileCount'))$('buildingFileCount').textContent=fileCount;if($('buildingBudget'))$('buildingBudget').textContent=money(x.budget);if($('buildingIndustries'))$('buildingIndustries').innerHTML=(x.industries||[]).length?(x.industries||[]).map(v=>`<span class=\\\"badge\\\">${esc(v)}</span>`).join(' '):'Brak przypisanych branż.';if($('buildingTeam'))$('buildingTeam').innerHTML=(x.team||[]).length?(x.team||[]).map(v=>`<div>• ${esc(v)}</div>`).join(''):'Brak przypisanej ekipy.';if($('buildingStages'))$('buildingStages').innerHTML=(x.stages||[]).length?(x.stages||[]).map((v,i)=>`<label class=\\\"checkrow\\\"><input type=\\\"checkbox\\\" style=\\\"width:auto\\\" ${v.done?'checked':''} onchange=\\\"setBuildingStage(${i},this.checked)\\\"><span>${esc(v.name)}</span></label>`).join(''):'Brak etapów.';if($('buildingMaterials'))$('buildingMaterials').innerHTML=(x.materials||[]).length?(x.materials||[]).map(v=>`<div class=\\\"meta\\\">• ${esc(v)}</div>`).join(''):'Brak wpisanych materiałów.';"
if old not in s: raise SystemExit('detail stats pattern not found')
s=s.replace(old,new,1)
insert="""
window.setBuildingStage=async(i,done)=>{if(!perm('edit'))return alert('Brak uprawnienia.');const x=current();if(!x)return;const stages=(x.stages||[]).map(v=>({...v}));if(!stages[i])return;stages[i].done=!!done;await setDoc(doc(db,'buildings',x.id),{stages,updatedAt:now()},{merge:true});await load();};
window.toggleBuildingStageEditor=()=>{const x=current();if(x)openBuildingForm(x.id)};
"""
marker="window.openFolderForm=parentId=>"
if marker not in s: raise SystemExit('folder marker not found')
s=s.replace(marker,insert+'\n'+marker,1)
s=s.replace("window.SerwisantModules.buildings={name:'Budowy / Projekty',version:'10.13',loaded:true,reload:load};", "window.SerwisantModules.buildings={name:'Budowy / Projekty',version:'10.18',loaded:true,reload:load};")
js.write_text(s,encoding='utf-8')
print('Buildings v10.18 patch applied')
